INSERT INTO system_configs (`key`, `value`) VALUES ('email_templates_json', '[{"id":"invite","name":"Solicitação de Convite","subject":"Você foi convidado para acessar ao VaiVistoriar!","html":"<!DOCTYPE html>\\n<html lang=\\"pt-BR\\">\\n  <body style=\\"margin:0; padding:0; background-color:#ffffff;\\">\\n    <table\\n      width=\\"100%\\"\\n      cellpadding=\\"0\\"\\n      cellspacing=\\"0\\"\\n      style=\\"background-color:#ffffff; padding:40px 0; font-family: Arial, Helvetica, sans-serif;\\"\\n    >\\n      <tr>\\n        <td align=\\"center\\">\\n\\n          <!-- Container -->\\n          <table\\n            width=\\"600\\"\\n            cellpadding=\\"0\\"\\n            cellspacing=\\"0\\"\\n            style=\\"background-color:#ffffff; border-radius:20px; padding:40px; box-shadow:0 20px 40px rgba(0,0,0,0.05);\\"\\n          >\\n\\n            <!-- Logo -->\\n            <tr>\\n              <td align=\\"center\\" style=\\"padding-bottom:30px;\\">\\n                <img\\n                  src=\\"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/avatars/landing/logo-1769124302334.png\\"\\n                  alt=\\"VaiVistoriar\\"\\n                  width=\\"200\\"\\n                  style=\\"width:200px; max-width:100%; height:auto; display:block;\\"\\n                />\\n              </td>\\n            </tr>\\n\\n            <!-- Ícone -->\\n            <tr>\\n              <td align=\\"center\\" style=\\"padding-bottom:20px;\\">\\n                <div\\n                  style=\\"width:64px; height:64px; background-color:#eef2ff; border-radius:18px; display:flex; align-items:center; justify-content:center;\\"\\n                >\\n                  <span style=\\"font-size:32px;\\">👥</span>\\n                </div>\\n              </td>\\n            </tr>\\n\\n            <!-- Título -->\\n            <tr>\\n              <td align=\\"center\\" style=\\"padding-bottom:10px;\\">\\n                <h1 style=\\"margin:0; font-size:24px; color:#1e293b;\\">\\n                  Convite para a equipe\\n                </h1>\\n              </td>\\n            </tr>\\n\\n            <!-- Saudação -->\\n            <tr>\\n              <td style=\\"padding-top:20px;\\">\\n                <p style=\\"margin:0; font-size:16px; color:#1e293b;\\">\\n                  Olá, <strong>{{user_name}}</strong>!\\n                </p>\\n              </td>\\n            </tr>\\n\\n            <!-- Texto -->\\n            <tr>\\n              <td style=\\"padding:15px 0 30px 0;\\">\\n                <p style=\\"margin:0; font-size:16px; line-height:1.6; color:#64748b;\\">\\n                  Você foi convidado para fazer parte da equipe do\\n                  <strong>VaiVistoriar</strong>.\\n                  Para acessar o sistema e concluir seu cadastro, clique no botão abaixo.\\n                </p>\\n              </td>\\n            </tr>\\n\\n            <!-- Botão -->\\n            <tr>\\n              <td align=\\"center\\" style=\\"padding-bottom:40px;\\">\\n                <a\\n                  href=\\"{{link}}\\"\\n                  style=\\"\\n                    display:inline-block;\\n                    background-color:#2563eb;\\n                    color:#ffffff;\\n                    padding:16px 36px;\\n                    border-radius:14px;\\n                    text-decoration:none;\\n                    font-size:16px;\\n                    font-weight:bold;\\n                    box-shadow:0 12px 20px rgba(37,99,235,0.35);\\n                  \\"\\n                >\\n                  Concluir cadastro\\n                </a>\\n              </td>\\n            </tr>\\n\\n            <!-- Aviso -->\\n            <tr>\\n              <td align=\\"center\\">\\n                <p style=\\"margin:0; font-size:13px; color:#94a3b8; line-height:1.5\\n"},{"id":"payment_success","name":"Confirmação de Pagamento","subject":"Seu pagamento foi confirmado!","html":"<!DOCTYPE html>\\n<html lang=\\"pt-BR\\">\\n  <body style=\\"margin:0; padding:0; background-color:#ffffff;\\">\\n    <table\\n      width=\\"100%\\"\\n      cellpadding=\\"0\\"\\n      cellspacing=\\"0\\"\\n      style=\\"background-color:#ffffff; padding:40px 0; font-family: Arial, Helvetica, sans-serif;\\"\\n    >\\n      <tr>\\n        <td align=\\"center\\">\\n\\n          <!-- Container -->\\n          <table\\n            width=\\"600\\"\\n            cellpadding=\\"0\\"\\n            cellspacing=\\"0\\"\\n            style=\\"\\n              background-color:#ffffff;\\n              border-radius:20px;\\n              padding:40px;\\n              border:1px solid #f1f5f9;\\n              box-shadow:0 10px 25px -5px rgba(0,0,0,0.05);\\n            \\"\\n          >\\n\\n            <!-- Logo -->\\n            <tr>\\n              <td align=\\"center\\" style=\\"padding-bottom:30px;\\">\\n                <img\\n                  src=\\"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/avatars/landing/logo-1769124302334.png\\"\\n                  alt=\\"VaiVistoriar\\"\\n                  width=\\"160\\"\\n                  style=\\"width:160px; max-width:100%; height:auto; display:block;\\"\\n                />\\n              </td>\\n            </tr>\\n\\n            <!-- Título -->\\n            <tr>\\n              <td align=\\"center\\" style=\\"padding-bottom:12px;\\">\\n                <h1\\n                  style=\\"\\n                    margin:0;\\n                    font-size:24px;\\n                    color:#1e293b;\\n                    font-weight:800;\\n                  \\"\\n                >\\n                  Pagamento confirmado 🎉\\n                </h1>\\n              </td>\\n            </tr>\\n\\n            <!-- Texto -->\\n            <tr>\\n              <td align=\\"center\\" style=\\"padding:12px 20px 30px 20px;\\">\\n                <p\\n                  style=\\"\\n                    margin:0;\\n                    font-size:16px;\\n                    line-height:1.6;\\n                    color:#64748b;\\n                  \\"\\n                >\\n                  O seu plano <strong>{{plan_name}}</strong> já está ativo\\n                  em sua conta. Aproveite todas as funcionalidades premium\\n                  do <strong>VistoriaPro</strong>.\\n                </p>\\n              </td>\\n            </tr>\\n\\n            <!-- Resumo do pagamento -->\\n            <tr>\\n              <td style=\\"padding-bottom:30px;\\">\\n                <table\\n                  width=\\"100%\\"\\n                  cellpadding=\\"0\\"\\n                  cellspacing=\\"0\\"\\n                  style=\\"\\n                    background-color:#f1f5f9;\\n                    border-radius:14px;\\n                    padding:20px;\\n                  \\"\\n                >\\n                  <tr>\\n                    <td style=\\"padding-bottom:8px;\\">\\n                      <p style=\\"margin:0; font-size:14px; color:#475569;\\">\\n                        Valor:\\n                        <strong>R$ {{amount}}</strong>\\n                      </p>\\n                    </td>\\n                  </tr>\\n                  <tr>\\n                    <td>\\n                      <p style=\\"margin:0; font-size:14px; color:#475569;\\">\\n                        Data:\\n                        <strong>{{date}}</strong>\\n                      </p>\\n                    </td>\\n                  </tr>\\n                </table>\\n              </td>\\n            </tr>\\n\\n            <!-- Observação -->\\n            <tr>\\n              <td align=\\"center\\">\\n                <p\\n                  style=\\"\\n                    margin:0;\\n                    font-size:14px;\\n                    color:#64748b;\\n                  \\"\\n                >\\n                  Em caso de dúvidas, nossa equipe está à disposição para ajudar.\\n                </p>\\n              </td>\\n            </tr>\\n\\