      </td>\\n            </tr>\\n\\n            <!-- Rodapé -->\\n            <tr>\\n              <td align=\\"center\\">\\n                <p\\n                  style=\\"\\n                    margin:0;\\n                    color:#94a3b8;\\n                    font-size:11px;\\n                  \\"\\n                >\\n                  VaiVistoriar © 2026 — Tecnologia para Vistorias Imobiliárias\\n                </p>\\n              </td>\\n            </tr>\\n\\n          </table>\\n\\n        </td>\\n      </tr>\\n    </table>\\n  </body>\\n</html>"}]') ON DUPLICATE KEY UPDATE `value`=VALUES(`value`);
