VALUES ('7f3aa08b-2e0f-42d0-8eca-ad451ddbdc60', '0eb959cf-bad8-4cac-95ce-3c084a4223c0', 'Luar Ponta Negra', 'Av. Perimetral Thales Loureiro, 1030 - Ponta Negra, Manaus - AM, 69037255', 'ALINE BASTOS BRILHANTE DE SOUSA', 'Entrada', '2026-06-30', 'Finalizada', NULL, NULL, NULL, '2026-07-03 19:32:31', '{"rooms":[{"id":"4ct7afte1","name":"Sala de Estar e Jantar","photos":[{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.25442281229161934.jpeg","caption":"Esquadria com varão e cortina em bom estado."},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.9526820724098939.jpeg","caption":"Sofá com marcas de uso em bom estado"},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.09668022125523268.jpeg","caption":"Sofá em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.715267470225433.jpeg","caption":"Painel com móvel em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.27353892950286285.jpeg","caption":"Gavetas do móvel em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.4255613228425251.jpeg","caption":"Poltrona de Apoio "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.17221129073566666.jpeg","caption":"Sala com Led´s em bom estado, pintura e piso em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.274602831850721.jpeg","caption":"Sala de Estar em bom estado e funcionamento "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.29044972791275214.jpeg","caption":"Marca de uso do sofá"},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.7775417754667704.jpeg","caption":"Retirada da cortina"}],"condition":"Bom","observations":"Ambiente de sala de estar integrado à varanda, com piso em cerâmica na cor clara, rodapés cerâmicos, paredes com pintura branca e teto em gesso liso, apresentando bom estado de conservação, sem fissuras, trincas ou avarias aparentes.\\n\\nO teto possui iluminação composta por painel de LED embutido e projeto luminotécnico com perfis lineares em LED embutidos no forro, em funcionamento durante a vistoria.\\n\\nUma das paredes possui painel planejado para televisão em MDF com acabamento marmorizado, composto por rack inferior suspenso com gavetas, nicho aberto e duas prateleiras superiores em MDF cinza, apresentando bom estado de conservação, sem danos aparentes. Foram observados pontos elétricos e passagem para instalação de televisão.\\n\\nA sala dispõe de cortina em tecido branco instalada em trilho suíço junto à porta de acesso à varanda, apresentando bom estado de conservação.\\n\\nFoi verificado sofá de dois lugares estofado em tecido cinza e poltrona estofada, ambos em bom estado geral de conservação, apresentando apenas discretas marcas de uso no estofamento do sofá.\\n\\nPorta de acesso à varanda em esquadria de alumínio branco com folhas de vidro de correr, em bom estado de conservação, proporcionando iluminação e ventilação natural ao ambiente.\\n\\nFoi solicitado pela inquilina a retirada da cortina da sala, foto com a esquadria sem cortina para deixar o registro no laudo."},{"id":"na0qx3oug","name":"Varanda","photos":[{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.5501027335761968.jpeg","caption":"Condensadoras em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.3939370726638435.jpeg","caption":"Esquadria de entrada para cozinha em bom estado."},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.2088720633162553.jpeg","caption":"Esquadria de entrada da Sala em bom estado, conjunto de varanda em bom estado."}],"condition":"Bom","observations":"Varanda descoberta com piso em cerâmica na cor clara, rodapés cerâmicos, guarda corpo metálico pintado na cor cinza e paredes externas revestidas com textura acrílica, apresentando bom estado geral de conservação, sem fissuras ou avarias aparentes.\\n\\nO acesso à varanda é realizado por porta de correr em esquadria de alumínio branco com vidro, apresentando funcionamento satisfatório e bom estado de conservação.\\n\\nO ambiente possui conjunto de mobiliário composto por uma mesa circular com tampo de vidro e duas cadeiras, ambos em bom estado de conservação.\\n\\nNa parede lateral encontram-se instaladas duas condensadoras de aparelhos de ar-condicionado tipo Split (marca Midea), fixadas em suportes metálicos, com tubulações aparentes devidamente isoladas e protegidas, sem indícios visíveis de vazamentos ou danos.\\n\\nFoi verificada ainda porta de correr em esquadria de alumínio branco e vidro que dá acesso à área de serviço, apresentando bom funcionamento e conservação.\\n\\nO piso possui ralo para escoamento de águas pluviais, sem obstruções aparentes durante a vistoria."},{"id":"pa6fv1lqb","name":"Cozinha","photos":[{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.11958001535794915.jpeg","caption":"Cozinha visão da varanda "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.047455266313190525.jpeg","caption":"Micro-ondas da marca Panasonic em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.25707096712385913.jpeg","caption":"Maquina de Lavar  Electrolux de 11 KG em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.4501990366962606.jpeg","caption":"Fogão Cooktop 04 bocas Electrolux em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.962356837035728.jpeg","caption":"Armário inferior em bom estado com torneira em funcionamento."},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.6579406177365118.jpeg","caption":""},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.1365628918795544.jpeg","caption":"Geladeira Electrolux com marcas de uso"},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.10113795131936543.jpeg","caption":"Geladeira na parte interna em perfeito estado"},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.8553171064838886.jpeg","caption":"Cozinha vista pela Sala"},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.0465872930918354.jpeg","caption":"Sugar instalado "}],"condition":"Bom","observations":"Cozinha integrada à área de serviço, equipada com armários planejados superiores e inferiores em MDF nas cores branco e cinza, com detalhes em amadeirado, portas dotadas de pistões a gás e dobradiças metálicas. \\nBancada em granito preto com cuba em aço inox e torneira metálica. \\nGeladeira da marca Electrolux com marcas de uso, em funcionamento, Cooktop da marca Electrolux de 04 bocas instalado sobre a bancada, Sugar Instalado da marca Electrolux, Microondas da marca Panasonic. Área de serviço equipada com  máquina de lavar roupas da marca Electrolux de 11 kg. \\nIluminação composta por luminárias lineares de LED. \\nRevestimentos cerâmicos em paredes e piso íntegros. \\nMobiliário e revestimentos apresentam bom estado de conservação, sem avarias aparentes."},{"id":"ddqgljli5","name":"Banheiro Social ","photos":[{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.1897893034252882.jpeg","caption":"Box em perfeito estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.4811715715326468.jpeg","caption":"Porta nova com chave "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.9833790423388593.jpeg","caption":"Cuba da pia em bom estado com água em funcionamento "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.8269347713096837.jpeg","caption":"Luz em funcionamento e exaustor em funcionamento "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.5765700023142842.jpeg","caption":"Bacia Sanitária com Caixa acoplada em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.7454233165119019.jpeg","caption":"Chuveiro Metálico em bom estado "}],"condition":"Bom","observations":"Banheiro revestido com piso e paredes em cerâmica na cor branca, apresentando bom estado de conservação, sem fissuras, trincas ou peças soltas aparentes.\\n\\nBox de banho confeccionado em vidro temperado incolor, com esquadrias em alumínio na cor preta e portas de correr, apresentando vidros íntegros, trilhos e ferragens em bom estado aparente.\\n\\nÁrea do banho equipada com base para chuveiro, ducha metálica tipo redonda e registros metálicos cromados. Revestimentos internos íntegros, sem avarias aparentes.\\n\\nBancada em granito claro (tipo granito branco/cinza), com cuba oval embutida em louça branca e torneira metálica cromada. Bancada íntegra, sem lascas ou trincas aparentes.\\n\\nBacia sanitária em louça branca com caixa acoplada, apresentando bom estado de conservação, sem avarias aparentes.\\nPorta equipada com fechadura e maçaneta metálicas, encontrando-se protegida por filme plástico.\\nTeto com pintura branca, equipado com luminária de LED embutida e exaustor elétrico, ambos em bom estado visual."},{"id":"mdd5muqgj","name":"Quarto 01","photos":[{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.6855597725312682.jpeg","caption":"Porta nova com chave em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.14998557139591728.jpeg","caption":"Split  em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.5307099888882718.jpeg","caption":"Lâmpada em bom estado, persiana em bom estado"},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.06291966820577066.jpeg","caption":"Tomadas e interruptor em bom estado"},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.24730971878506125.jpeg","caption":""}],"condition":"Bom","observations":"Dormitório com piso laminado amadeirado, rodapés em MDF na cor amadeirada, paredes e teto com pintura na cor branca, apresentando bom estado de conservação, sem fissuras, trincas ou avarias aparentes.\\n\\nJanela em esquadria de alumínio branco com folhas de vidro e persiana tipo rolo instalada, apresentando bom estado de conservação e funcionamento aparente.\\n\\nEquipado com aparelho de ar-condicionado Split hi-wall, marca Midea, instalado na parede, com acabamento e tubulação embutida. Equipamento em bom estado visual de conservação.\\n\\nPorta em bom estado  equipada com fechadura, maçaneta metálica e dobradiças em bom estado aparente, permanecendo protegida por filme plástico.\\n\\nTeto com luminária de LED embutida em funcionamento durante a vistoria."},{"id":"lhvj44phv","name":"Quarto 02 - Suíte ","photos":[{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.16787739765254162.jpeg","caption":"Banheiro da Suíte em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.41102645877177557.jpeg","caption":"Bacia Sanitária com Caixa acoplada em bom estado, Box de vidro em bom estado."},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.5003739289616488.jpeg","caption":"Porta do banheiro nova com chave em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.8168384162460305.jpeg","caption":"Chuveiro Elétrico novo em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.8193479176749084.jpeg","caption":"Luz em bom estado, Exaustor em bom estado."},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.7696758194815866.jpeg","caption":"Porta de Acesso da suíte com chave em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.4091706897394163.jpeg","caption":"Split da Suíte em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.7217855516053882.jpeg","caption":"Armário suspenso em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.5393778357808128.jpeg","caption":"Guarda-Roupa novo em bom estado"},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.5489754999508311.jpeg","caption":"Guarda-roupa parte interna em bom estado "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.07751489308612425.jpeg","caption":"Persiana em bom estado, pintura em bom estado, piso em bom estado."},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.19570117424716493.jpeg","caption":"Controles dos ares condicionados com pilha e em funcionamento "},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.3366100498633674.jpeg","caption":"obs 1 - foto do roupeiro"},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.8610544471239945.jpeg","caption":"obs 2 - foto do roupeiro"},{"url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.2977333650976549.jpeg","caption":"obs 3 - foto do roupeiro com aparencia de mofo."}],"condition":"Bom","observations":"Dormitório com piso laminado amadeirado, rodapés em MDF na cor amadeirada, paredes e teto com pintura branca, apresentando bom estado de conservação, sem fissuras, trincas ou avarias aparentes.\\n\\nAmbiente equipado com janela em esquadria de alumínio branco com folhas de vidro e persiana tipo rolo instalada, permitindo iluminação e ventilação natural. Esquadria e persiana encontram-se em bom estado de conservação.\\n\\nInstalado aparelho de ar-condicionado Split hi-wall, marca Midea, fixado em parede, com acabamento e tubulação embutida, apresentando bom estado visual de conservação.\\n\\nSuíte equipada com guarda-roupa planejado em MDF na cor cinza, composto por quatro portas de abrir, cabideiros, gavetas internas, prateleiras e maleiro superior. Mobiliário apresenta bom estado de conservação, com ferragens, dobradiças, corrediças e puxadores íntegros e funcionamento aparente satisfatório.\\nPorta de acesso equipada com fechadura, maçanetas e dobradiças metálicas, permanecendo protegida por filme plástico.\\n\\nBanheiro da Suíte\\n\\nDescrição Geral:\\n\\nBanheiro privativo revestido com piso e paredes em cerâmica branca, apresentando bom estado de conservação, sem trincas, fissuras ou peças soltas aparentes.\\n\\nBancada em granito claro com cuba oval embutida em louça branca e torneira metálica cromada. Bancada íntegra, sem lascas ou trincas aparentes.\\n\\nBacia sanitária em louça branca com caixa acoplada, apresentando bom estado de conservação.\\n\\nÁrea de banho delimitada por box em vidro temperado incolor com perfis em alumínio preto e portas de correr. Vidros, perfis, trilhos e ferragens encontram-se íntegros.\\n\\nÁrea do chuveiro equipada com chuveiro elétrico branco instalado na parede, além de registro metálico cromado. Revestimentos internos do box em bom estado de conservação.\\n\\nTeto com pintura branca e luminária de LED embutida em funcionamento durante a vistoria.\\n\\nHouve observação da parte da inquilina no Roupeiro do quarto com mofo. Houve a limpeza, porém esta em observação as fotos abaixo."}],"keys_data":{"delivered":true,"photo_url":"https://cmrgzaoexmjilvbuduek.supabase.co/storage/v1/object/public/inspection-photos/0.33355477874432227.jpeg","description":"Chaveiro contendo duas chaves, chave 01 - entrada do bloco, chave 02 - porta de entrada do apartamento."},"general_observations":"","extra_costs":[],"broker_data":{"id":"a1e086f8-81d3-4f8f-93ec-270554d0f2c6","cep":null,"city":null,"role":"BROKER","creci":null,"email":"jamile.melooliveira@gmail.com","phone":null,"state":null,"number":null,"status":"Ativo","street":null,"address":null,"user_id":"0eb959cf-bad8-4cac-95ce-3c084a4223c0","cpf_cnpj":"01272650235","district":null,"full_name":"Jamile Melo Oliveira Vieira","avatar_url":null,"complement":null,"updated_at":"2026-05-14T16:53:20.411686+00:00","last_access":null,"company_name":null,"parent_pj_id":null,"current_session_id":"wzdrhpapqeomr0v4afs","subscription_plan_id":"fd4c420f-09b2-40a7-b43f-972e21378368","subscription_expires_at":"2036-01-01T04:00:00+00:00"}}')
